class SellerRepositoryImpl implements SellerRepository { const SellerRepositoryImpl(this._r); final SellerRemoteDataSource _r; @override Future<Map<String,dynamic>> dashboard()=>_r.dashboard(); @override Future<List<Map<String,dynamic>>> listings()=>_r.listings(); @override Future<Map<String,dynamic>> createListing(Map<String,dynamic>d)=>_r.createListing(d); @override Future<Map<String,dynamic>> updateListing(int i,Map<String,dynamic>d)=>_r.updateListing(i,d); @override Future<void> deleteListing(int i)=>_r.deleteListing(i); @override Future<Map<String,dynamic>> setListingStatus(int i,String s)=>_r.setListingStatus(i,s); @override Future<List<Map<String,dynamic>>> bookings()=>_r.bookings(); @override Future<Map<String,dynamic>> updateBooking(int i,String s)=>_r.updateBooking(i,s); @override Future<List<Map<String,dynamic>>> leads()=>_r.leads(); @override Future<Map<String,dynamic>> updateLead(int i,String s)=>_r.updateLead(i,s); @override Future<List<String>> uploadImages(List<File> f)=>_r.uploadImages(f); @override Future<Map<String,dynamic>> account()=>_r.account(); @override Future<Map<String,dynamic>> updateAccount(Map<String,dynamic>d)=>_r.updateAccount(d); @override Future<List<Map<String,dynamic>>> notifications()=>_r.notifications(); @override Future<void> markNotificationsRead()=>_r.markNotificationsRead(); }
